import java.util.*; import java.io.*; public class Main { static class FastScanner { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st; String next() { while (st == null || !st.hasMoreTokens()) { try { String l = br.readLine(); if (l == null) return null; st = new StringTokenizer(l); } catch (IOException e) { return null; } } return st.nextToken(); } int nextInt() { return Integer.parseInt(next()); } } public static void main(String[] args) throws Exception { FastScanner sc = new FastScanner(); PrintWriter out = new PrintWriter(System.out); int t = sc.nextInt(); while (t-- > 0) { int n = sc.nextInt(); int[] a = new int[n]; for (int i = 0; i < n; i++) { a[i] = sc.nextInt(); } int k = sc.nextInt(); boolean[] isDisliked = new boolean[n + 1]; for (int i = 0; i < k; i++) { isDisliked[sc.nextInt()] = true; } StringBuilder sb = new StringBuilder(); boolean first = true; for (int i = 0; i < n; i++) { if (!isDisliked[a[i]]) { if (!first) sb.append(" "); sb.append(a[i]); first = false; } } out.println(sb.toString()); } out.flush(); out.close(); } }